const PNG_BASE64 =
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';

const JPEG_BASE64 =
  '';

const MP4_HEX = '000000186674797069736f6d0000020069736f6d69736f320000000866726565';

export function pngImage(): Buffer {
  return Buffer.from(PNG_BASE64, 'base64');
}

export function jpegImage(): Buffer {
  return Buffer.from(JPEG_BASE64, 'base64');
}

export function truncatedPngImage(): Buffer {
  return pngImage().subarray(0, 33);
}

export function svgDocument(): Buffer {
  return Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>');
}

export function htmlDocument(): Buffer {
  return Buffer.from('<html><script>alert(1)</script></html>');
}

export function mp4Video(): Buffer {
  return Buffer.from(MP4_HEX, 'hex');
}
